import json, re
def flexible(s):
    if len(s)>300: s=s[-300:]
    ans=re.findall(r'(\-?[0-9\.\,]+)', s)
    for a in reversed(ans):
        if a not in ('', '.'): return a.replace(',','')
    return None
for f in ['val_generations/0.jsonl','val_generations/25.jsonl']:
    print('=====',f)
    n=0
    for d in [json.loads(l) for l in open(f)]:
        pred=flexible(d['output']); sc=1.0 if pred==d['gts'] else 0.0
        if abs(sc-d['score'])>1e-9:
            n+=1
            if n<=4:
                print('gts=',repr(d['gts']),'pred=',repr(pred),'score=',d['score'],'| tail:',repr(d['output'][-120:]))
    print('total mismatches', n)
EOF

